create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.characters(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,level integer check(level is null or(level>=1 and level<=300)),job text not null,server text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.listings(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,character_id uuid references public.characters(id) on delete set null,category text not null check(category in('priest','party','boss','guild','partner')),title text not null,subtitle text,server text not null,status text not null default 'active',description text,tags text[] not null default '{}',details jsonb not null default '{}'::jsonb,expires_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists listings_category_created_idx on public.listings(category,created_at desc);
create index if not exists listings_user_idx on public.listings(user_id,created_at desc);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
drop trigger if exists characters_set_updated_at on public.characters; create trigger characters_set_updated_at before update on public.characters for each row execute function public.set_updated_at();
drop trigger if exists listings_set_updated_at on public.listings; create trigger listings_set_updated_at before update on public.listings for each row execute function public.set_updated_at();
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name','')) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.characters enable row level security; alter table public.listings enable row level security;
drop policy if exists "Profiles are publicly readable" on public.profiles; create policy "Profiles are publicly readable" on public.profiles for select using(true);
drop policy if exists "Users can update own profile" on public.profiles; create policy "Users can update own profile" on public.profiles for update using(auth.uid()=id) with check(auth.uid()=id);
drop policy if exists "Characters are publicly readable" on public.characters; create policy "Characters are publicly readable" on public.characters for select using(true);
drop policy if exists "Users can insert own characters" on public.characters; create policy "Users can insert own characters" on public.characters for insert with check(auth.uid()=user_id);
drop policy if exists "Users can update own characters" on public.characters; create policy "Users can update own characters" on public.characters for update using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "Users can delete own characters" on public.characters; create policy "Users can delete own characters" on public.characters for delete using(auth.uid()=user_id);
drop policy if exists "Visible listings are publicly readable" on public.listings; create policy "Visible listings are publicly readable" on public.listings for select using(status<>'paused' or auth.uid()=user_id);
drop policy if exists "Users can insert own listings" on public.listings; create policy "Users can insert own listings" on public.listings for insert with check(auth.uid()=user_id and(character_id is null or exists(select 1 from public.characters c where c.id=character_id and c.user_id=auth.uid())));
drop policy if exists "Users can update own listings" on public.listings; create policy "Users can update own listings" on public.listings for update using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "Users can delete own listings" on public.listings; create policy "Users can delete own listings" on public.listings for delete using(auth.uid()=user_id);
